/**
 * Dress My Wound — official product identity (emblem + wordmark), drawn from vector paths traced
 * from the supplied reference artwork (./dmw-artwork.ts, generated by
 * scripts/brand/trace-dmw-reference.py). Shapes are never redrawn by hand; this module only paints
 * them. One SVG builder serves the asset generator (app icons, splash, store graphics), the mobile
 * app (react-native-svg `SvgXml`) and the admin console, so every surface shows the same artwork.
 *
 *   emblem   — cross, heart, ECG pulse and leaf. No text: the app icon and small marks.
 *   wordmark — emblem + "Dress My Wound" letterforms, as supplied. The admin console adds its
 *              subtitle ("Operations & clinical review console") as live text, never in the artwork;
 *              the Arabic name غير لي is always set as text next to the artwork, never inside it.
 */

/** Brand-board colours of the supplied Dress My Wound reference. */
export const dmwColors = {
  /** Primary Orange. */
  orange: '#F97316',
  /** Text / Dark — "Dress My" on light surfaces. */
  ink: '#1F2937',
  /** "Dress My" on dark surfaces (soft white). */
  inkInverse: '#F8FAFC',
  /** Medical Silver. */
  silver: '#9CA3AF',
  /** Soft cream (light icon glass). */
  cream: '#FFF7EE',
  /** Deep navy (dark icon glass). */
  navy: '#0F172A',
} as const;

type Stop = readonly [offset: number, color: string, opacity?: number];
type Gradient = { x1: number; y1: number; x2: number; y2: number; stops: readonly Stop[] };

/** The reference's light-to-deep shading, as gradients over each shape's bounding box. */
export const dmwGradients = {
  orange: { x1: 0.8, y1: 0, x2: 0.2, y2: 1, stops: [[0, '#FFAE5C'], [0.55, dmwColors.orange], [1, '#EA580C']] },
  silver: { x1: 0.15, y1: 0, x2: 0.7, y2: 1, stops: [[0, '#D1D5DB'], [0.6, '#A3A9B2'], [1, '#8A919B']] },
  // The ECG trace fades in from the left, as in the reference.
  ecg: { x1: 0, y1: 0, x2: 1, y2: 0, stops: [[0, dmwColors.orange, 0], [0.35, dmwColors.orange], [1, '#F26A12']] },
  wound: { x1: 0, y1: 0, x2: 0, y2: 1, stops: [[0, '#FB923C'], [1, '#EA580C']] },
} as const satisfies Record<string, Gradient>;

/** The artwork's paths (structural type of ./dmw-artwork.ts). */
export type DmwArtwork = {
  readonly emblem: { readonly orange: string; readonly silver: string; readonly ecg: string; readonly bounds: readonly number[] };
  readonly text: { readonly dark: string; readonly orange: string; readonly bounds: readonly number[] };
};

export type DmwPart = 'emblem' | 'wordmark';

export type DmwPaintOptions = {
  part: DmwPart;
  /** "Dress My" colour: dark ink on light surfaces, soft white on dark ones. */
  inverse?: boolean;
  /**
   * Flat colours instead of the gradients — themed / tinted / monochrome icons. Any colour left out
   * falls back to `all`.
   */
  flat?: { all?: string; orange?: string; silver?: string; ecg?: string; ink?: string; wound?: string };
  /** Prefix for gradient ids — must be unique per document when several marks share a page. */
  idPrefix?: string;
};

/** Padding (reference px) kept around the traced bounds so anti-aliased edges are never clipped. */
const PAD = 2;

/** The artwork's box in reference coordinates: [x, y, width, height]. */
export function dmwBox(art: DmwArtwork, part: DmwPart): [number, number, number, number] {
  const e = art.emblem.bounds;
  const t = art.text.bounds;
  const [x0, y0, x1, y1] = part === 'emblem' ? [e[0]!, e[1]!, e[2]!, e[3]!] : [Math.min(e[0]!, t[0]!), Math.min(e[1]!, t[1]!), Math.max(e[2]!, t[2]!), Math.max(e[3]!, t[3]!)];
  return [x0 - PAD, y0 - PAD, x1 - x0 + 2 * PAD, y1 - y0 + 2 * PAD];
}

/** Aspect ratio (width / height) of a part. */
export function dmwAspect(art: DmwArtwork, part: DmwPart): number {
  const [, , w, h] = dmwBox(art, part);
  return w / h;
}

function gradient(id: string, g: Gradient, flat?: string): string {
  const stops = g.stops.map(([offset, color, opacity]) => `<stop offset="${offset}" stop-color="${flat ?? color}"${opacity === undefined ? '' : ` stop-opacity="${opacity}"`}/>`).join('');
  return `<linearGradient id="${id}" x1="${g.x1}" y1="${g.y1}" x2="${g.x2}" y2="${g.y2}">${stops}</linearGradient>`;
}

/**
 * The artwork as SVG fragments in reference coordinates (`box` is its tight box), so callers can
 * place it inside a larger canvas (icons) or wrap it with `dmwSvg`.
 */
export function dmwParts(art: DmwArtwork, opts: DmwPaintOptions): { defs: string; body: string; box: [number, number, number, number] } {
  const p = opts.idPrefix ?? 'dmw';
  const f = opts.flat;
  const pick = (k: 'orange' | 'silver' | 'ecg' | 'ink' | 'wound') => f?.[k] ?? f?.all;
  const ink = pick('ink') ?? (opts.inverse ? dmwColors.inkInverse : dmwColors.ink);
  const defs: string[] = [gradient(`${p}-ecg`, dmwGradients.ecg, pick('ecg'))];
  const fill = (k: 'orange' | 'silver' | 'wound') => {
    const s = pick(k);
    if (s) return s;
    defs.push(gradient(`${p}-${k}`, dmwGradients[k]));
    return `url(#${p}-${k})`;
  };
  const body = [
    `<path d="${art.emblem.silver}" fill="${fill('silver')}" fill-rule="evenodd"/>`,
    `<path d="${art.emblem.orange}" fill="${fill('orange')}" fill-rule="evenodd"/>`,
    `<path d="${art.emblem.ecg}" fill="url(#${p}-ecg)" fill-rule="evenodd"/>`,
  ];
  if (opts.part === 'wordmark') {
    body.push(`<path d="${art.text.dark}" fill="${ink}" fill-rule="evenodd"/>`, `<path d="${art.text.orange}" fill="${fill('wound')}" fill-rule="evenodd"/>`);
  }
  return { defs: defs.join(''), body: body.join(''), box: dmwBox(art, opts.part) };
}

/** A complete, self-contained SVG document of the emblem or the wordmark. */
export function dmwSvg(art: DmwArtwork, opts: DmwPaintOptions & { width?: number; height?: number; title?: string }): string {
  const { defs, body, box } = dmwParts(art, opts);
  const size = `${opts.width === undefined ? '' : ` width="${opts.width}"`}${opts.height === undefined ? '' : ` height="${opts.height}"`}`;
  const title = opts.title ? `<title>${opts.title}</title>` : '';
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${box.join(' ')}"${size}${opts.title ? ' role="img"' : ''}>${title}<defs>${defs}</defs>${body}</svg>`;
}
